<?php use App\Core\Auth; ?><section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="payments"><?php field('from','From','date',$_GET['from']??'',false); field('to','To','date',$_GET['to']??'',false); selectField('method','Payment method',['Cash','Bank','Mobile Money','Cheque','Other'],$_GET['method']??'',false); ?><button class="button">Filter payments</button><?php if(Auth::can('payments.write')): ?><a href="<?= e(url('invoices')) ?>" class="button primary">Record against an invoice →</a><?php endif ?></form><div class="table-wrap"><table><thead><tr><th>Receipt / date</th><th>Student</th><th>Invoice</th><th>Method / reference</th><th class="num">Amount</th><th>Received by</th><th>Status</th></tr></thead><tbody><?php if(!$rows) emptyRow(7); foreach(array_slice($rows,0,50) as $p): ?><tr><td><a href="<?= e(url('receipt',['id'=>$p['id']])) ?>"><?= e($p['receipt_number']) ?></a><small><?= e($p['paid_on']) ?></small></td><td><?= e($p['first_name'].' '.$p['last_name']) ?><small><?= e($p['admission_number']) ?></small></td><td><a href="<?= e(url('invoice',['id'=>$p['invoice_id']])) ?>"><?= e($p['invoice_number']) ?></a></td><td><?= e($p['method']) ?><small><?= e($p['reference']??'—') ?></small></td><td class="num"><?= money($p['amount']) ?></td><td><?= e($p['received_name']) ?></td><td><?php badge($p['reversed_at']?'Reversed':'Posted'); if(!$p['reversed_at'] && Auth::can('payments.reverse')): ?><details><summary class="small-link">Reverse</summary><?php startForm('payment.reverse',['payment_id'=>$p['id']],'stack'); field('reason','Reason for reversal'); ?><button class="button danger" data-confirm="Reverse this payment and restore the invoice balance?">Confirm reversal</button></form></details><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php pagination(max(1,(int)($_GET['p']??1)),count($rows)>50); ?></section>
